import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DYYBR_aZ.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"java/JAVA数据类型.md","filePath":"java/JAVA数据类型.md"}'),d={name:"java/JAVA数据类型.md"};function s(l,e,c,r,i,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h2 id="java数据类型" tabindex="-1">JAVA数据类型 <a class="header-anchor" href="#java数据类型" aria-label="Permalink to &quot;JAVA数据类型&quot;">​</a></h2><p>Java 里有两套数值体系：<strong>基本类型</strong>存“原始值”，<strong>包装类</strong>把它们包装成对象。日常写代码时，基本类型更轻更快，包装类更适合集合、泛型、数据库字段和需要 <code>null</code> 的场景。</p><h3 id="_8-种基本类型和对应包装类" tabindex="-1"><strong>8 种基本类型和对应包装类</strong> <a class="header-anchor" href="#_8-种基本类型和对应包装类" aria-label="Permalink to &quot;**8 种基本类型和对应包装类**&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">基本类型</th><th style="text-align:center;">包装类</th><th style="text-align:center;">默认值</th></tr></thead><tbody><tr><td style="text-align:center;"><code>byte</code></td><td style="text-align:center;"><code>Byte</code></td><td style="text-align:center;"><code>0</code></td></tr><tr><td style="text-align:center;"><code>short</code></td><td style="text-align:center;"><code>Short</code></td><td style="text-align:center;"><code>0</code></td></tr><tr><td style="text-align:center;"><code>int</code></td><td style="text-align:center;"><code>Integer</code></td><td style="text-align:center;"><code>0</code></td></tr><tr><td style="text-align:center;"><code>long</code></td><td style="text-align:center;"><code>Long</code></td><td style="text-align:center;"><code>0L</code></td></tr><tr><td style="text-align:center;"><code>float</code></td><td style="text-align:center;"><code>Float</code></td><td style="text-align:center;"><code>0.0f</code></td></tr><tr><td style="text-align:center;"><code>double</code></td><td style="text-align:center;"><code>Double</code></td><td style="text-align:center;"><code>0.0d</code></td></tr><tr><td style="text-align:center;"><code>char</code></td><td style="text-align:center;"><code>Character</code></td><td style="text-align:center;"><code>&#39;\\u0000&#39;</code></td></tr><tr><td style="text-align:center;"><code>boolean</code></td><td style="text-align:center;"><code>Boolean</code></td><td style="text-align:center;"><code>false</code></td></tr></tbody></table><h3 id="核心区别" tabindex="-1"><strong>核心区别</strong> <a class="header-anchor" href="#核心区别" aria-label="Permalink to &quot;**核心区别**&quot;">​</a></h3><ul><li><strong>本质不同</strong>：基本类型不是对象；包装类是对象，继承 <code>Object</code>。</li><li><strong>默认值不同</strong>：基本类型有固定默认值；包装类默认值是 <code>null</code>。</li><li><strong>能否为 null</strong>：基本类型不能为 <code>null</code>；包装类可以，所以适合表示“可能没有值”的场景，比如数据库字段、接口参数。</li><li><strong>存储和性能</strong>：基本类型直接存值，开销小；包装类是堆上的对象，有额外开销。</li><li><strong>集合和泛型</strong>：<code>List</code>、<code>Map</code> 等集合只能存对象，不能写 <code>List</code>，必须用 <code>List</code>。</li><li><strong>比较方式</strong>：基本类型用 <code>==</code> 比较值；包装类比较值要用 <code>equals()</code>，不要用 <code>==</code>。</li></ul><h3 id="自动装箱-自动拆箱" tabindex="-1"><strong>自动装箱 / 自动拆箱</strong> <a class="header-anchor" href="#自动装箱-自动拆箱" aria-label="Permalink to &quot;**自动装箱 / 自动拆箱**&quot;">​</a></h3><p>这是编译器提供的语法糖，不是 JVM 运行时魔法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer a = 10;   // 自动装箱，底层是 Integer.valueOf(10)</span></span>
<span class="line"><span>int b = a;        // 自动拆箱，底层是 a.intValue()</span></span></code></pre></div><h3 id="包装类缓存机制" tabindex="-1"><strong>包装类缓存机制</strong> <a class="header-anchor" href="#包装类缓存机制" aria-label="Permalink to &quot;**包装类缓存机制**&quot;">​</a></h3><p><code>Integer.valueOf()</code> 会复用 <code>-128 ~ 127</code> 范围内的对象，所以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer a = 127;</span></span>
<span class="line"><span>Integer b = 127;</span></span>
<span class="line"><span>System.out.println(a == b); // true，缓存复用同一对象</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Integer c = 128;</span></span>
<span class="line"><span>Integer d = 128;</span></span>
<span class="line"><span>System.out.println(c == d); // false，超出缓存范围，是新对象</span></span></code></pre></div><p><code>Byte</code>、<code>Short</code>、<code>Long</code>、<code>Character</code> 也有类似缓存；<code>Float</code>、<code>Double</code> 没有缓存。</p><h3 id="两个高频坑" tabindex="-1"><strong>两个高频坑</strong> <a class="header-anchor" href="#两个高频坑" aria-label="Permalink to &quot;**两个高频坑**&quot;">​</a></h3><ol><li><strong>包装类比较用 <code>equals()</code></strong><code>==</code> 比较的是对象引用，受缓存影响，结果不可靠。</li><li><strong>自动拆箱可能 NPE</strong> 如果包装类是 <code>null</code>，拆箱时会抛 <code>NullPointerException</code>。</li></ol><p>编辑</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer x = null;</span></span>
<span class="line"><span>int y = x; // NullPointerException</span></span></code></pre></div><h3 id="开发怎么选" tabindex="-1"><strong>开发怎么选</strong> <a class="header-anchor" href="#开发怎么选" aria-label="Permalink to &quot;**开发怎么选**&quot;">​</a></h3><ul><li>局部变量、循环计数、纯数值计算：优先用 <strong>基本类型</strong>。</li><li>集合、泛型、数据库实体字段、RPC 参数、可能为空的值：用 <strong>包装类</strong>。</li><li>包装类之间比较值：统一用 <strong><code>equals()</code></strong>。</li></ul>`,19)])])}const u=t(d,[["render",s]]);export{h as __pageData,u as default};
